"""Original reproductive chapter: contemporary PCOS diagnosis and management."""
from qbank_authoring import question,ref,finalize
PC=ref('International Evidence-Based PCOS Guideline, 2023','https://pmc.ncbi.nlm.nih.gov/articles/PMC10477934/')
PO=ref('ESHRE/ASRM/IMS: Premature Ovarian Insufficiency Guideline, 2024','https://academic.oup.com/hropen/article/2024/4/hoae065/7918369')
FH=ref('Endocrine Society: Functional Hypothalamic Amenorrhea Guideline','https://doi.org/10.1210/jc.2017-00131')
TE=ref('Endocrine Society: Testosterone Therapy in Men With Hypogonadism','https://doi.org/10.1210/jc.2018-00229')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('An adult has persistent oligo-ovulation and clinical hyperandrogenism after relevant mimics are excluded. What is the role of ultrasound in establishing PCOS?', 'It is not required when those two diagnostic components are already present',[
 ('Polycystic morphology is mandatory in every adult','The adult framework requires two of three components, not all three.'),('Ultrasound alone proves PCOS in every person','Morphology can occur without the syndrome.'),('A normal ovary scan excludes PCOS despite both components','It does not.')],
 'Use a syndrome-based adult diagnostic framework', '**Adult diagnosis uses ovulatory dysfunction, hyperandrogenism and PCOM, with at least two after exclusions.**',['AMH can substitute for ultrasound-defined PCOM in adults under the guideline.','Neither test should be added reflexively when unnecessary.'], '**Avoid both overtesting and overdiagnosis.**',['Assess metabolic and psychological consequences.','A diagnosis is not solely a count of ovarian follicles.'],[['Adult components','Two of three'],['Two clinical components present','No mandatory ultrasound'],['Exclusions','Still essential']],[PC],'clinical_scenario')
q('Which diagnostic approach is recommended for PCOS in adolescents?', 'Both persistent ovulatory dysfunction appropriate to time since menarche and hyperandrogenism, after exclusions',[
 ('Ultrasound follicle appearance alone','Normal adolescent ovaries commonly overlap with PCOM.'),('AMH alone','AMH is not recommended for adolescent diagnosis.'),('Any irregular cycle in the first year after menarche','Early pubertal irregularity can be physiological.')],
 'Adolescent physiology reduces the specificity of adult morphology criteria', '**The guideline requires both core clinical domains.**',['Cycle interpretation depends on years since menarche.','Ultrasound and AMH should not be used as adolescent diagnostic substitutes.'], '**Use follow-up when features are incomplete.**',['An “at risk” designation can support reassessment without premature labeling.','Treat troubling symptoms and risk factors appropriately during evaluation.'],[['Adolescents','Both dysfunction and hyperandrogenism'],['Morphology/AMH','Not diagnostic substitutes'],['Uncertain case','Longitudinal reassessment']],[PC])
q('What is the appropriate role of AMH in the 2023 adult PCOS guideline?', 'An alternative method of defining PCOM within the diagnostic algorithm, not a standalone PCOS test',[
 ('It replaces clinical and exclusion assessment entirely','The syndrome still requires the full framework.'),('Use both AMH and ultrasound in every adult to maximize the number of diagnoses','The guideline cautions against unnecessary duplication and overdiagnosis.'),('Apply one universal cutoff regardless of age, assay or contraception','AMH interpretation depends on these factors.')],
 'A new test option does not create a one-test diagnosis', '**AMH can reflect follicle abundance in adults.**',['Age, assay and hormonal contraception affect values.','It is not recommended in adolescents for diagnosis.'], '**Use one appropriate PCOM pathway when needed.**',['Do not add a test that will not change the diagnosis.','Explain that a high AMH alone is not synonymous with PCOS.'],[['Adult use','PCOM alternative'],['Not sufficient','Standalone diagnosis'],['Adolescent use','Not recommended']],[PC])
q('Oligomenorrhea and hirsutism suggest PCOS. Which baseline exclusion set is commonly appropriate?', 'Pregnancy when relevant, thyroid disease, hyperprolactinemia and nonclassic congenital adrenal hyperplasia',[
 ('No exclusions are needed once hirsutism is present','Several disorders can mimic the syndrome.'),('Only a random insulin concentration','It does not exclude the main mimics.'),('Routine adrenal surgery before biochemical testing','This is not a diagnostic pathway.')],
 'A common syndrome still requires exclusion of important alternatives', '**An early-morning 17-hydroxyprogesterone can screen for nonclassic 21-hydroxylase deficiency.**',['More severe or atypical findings warrant additional Cushing or tumor evaluation.','Medication and androgen exposure also matter.'], '**Use targeted tests rather than an indiscriminate panel.**',['Assess the chronology and severity.','Interpret borderline results with appropriate confirmatory testing.'],[['Common exclusions','Thyroid, prolactin and NCCAH'],['Amenorrhea','Exclude pregnancy'],['Atypical severe course','Broader targeted evaluation']],[PC],'clinical_scenario')
q('Rapidly progressive virilization, deepening voice and new severe androgen excess develop over several months. What is the correct principle?', 'Investigate an androgen-secreting tumor or other atypical cause rather than assuming routine PCOS',[
 ('Virilization speed has no diagnostic significance','Rapid progression is an important warning sign.'),('A polycystic-looking ovary excludes a tumor','Morphology does not eliminate another source.'),('One assay-independent testosterone cutoff perfectly identifies the source','Assay and clinical interpretation remain necessary.')],
 'Time course can be more discriminating than a mild chronic symptom', '**Overt virilization is atypical for ordinary PCOS.**',['Ovarian and adrenal causes need consideration.','Confirm a major biochemical elevation with a reliable method when needed.'], '**Arrange prompt specialist localization.**',['Interpret testosterone and DHEAS as clues rather than absolute source labels.','Do not delay assessment with months of empiric cosmetic therapy alone.'],[['Chronic mild course','Often PCOS pattern'],['Rapid virilization','Tumor/other cause warning'],['Response','Prompt biochemical and source evaluation']],[PC],'clinical_scenario')
q('Which test is the most accurate glycemic assessment in PCOS according to the international guideline, regardless of BMI?', 'A 75-g OGTT',[
 ('A random insulin level as a routine diagnostic substitute','Insulin assays are not recommended as routine clinical classification tools.'),('Urine glucose alone','It misses many abnormalities.'),('Testing is unnecessary in lean PCOS','Glycemic risk is increased across BMI categories.')],
 'PCOS carries metabolic risk beyond body size', '**OGTT detects impaired glucose tolerance that fasting glucose or A1C can miss.**',['Alternative tests can be used when OGTT is not feasible but have limitations.','Pregnancy planning is an especially important reassessment point.'], '**Assess broader cardiovascular risk as well.**',['Blood pressure, lipids, sleep and family history matter.','Use periodic follow-up based on risk.'],[['Preferred glycemic test','75-g OGTT'],['BMI','Does not remove the indication'],['Other risk','BP, lipids and related factors']],[PC])
q('An adult with PCOS is not seeking pregnancy and wants treatment for irregular cycles and hirsutism. Which is a common first pharmacological option when eligible?', 'A combined oral contraceptive',[
 ('Letrozole as routine long-term hirsutism treatment','Its main role is ovulation induction in a fertility pathway.'),('Metformin as a guaranteed superior cosmetic treatment in every patient','It is mainly selected for metabolic indications and has different benefits.'),('An antiandrogen without any contraception discussion','Fetal exposure must be prevented.')],
 'Match therapy to the symptom and reproductive goal', '**Combined contraceptives can regulate bleeding and reduce androgen-related symptoms.**',['VTE, migraine, smoking and other standard contraindications require review.','No single preparation is universally preferred.'], '**Use the lowest appropriate effective hormonal exposure and shared choice.**',['Cosmetic hair-reduction methods can complement treatment.','Discuss that hair response takes time.'],[['Goal','Cycle and androgen-symptom control'],['Option','Eligible combined contraceptive'],['Safety','Standard contraceptive risk assessment']],[PC],'clinical_scenario')
q('Which PCOS treatment goal most directly supports metformin selection?', 'Metabolic outcomes, particularly in adults with higher BMI or dysglycemic risk',[
 ('It is the most effective ovulation agent in every infertility case','Letrozole is preferred for suitable anovulatory infertility.'),('It eliminates the need for lifestyle support','The approaches are complementary.'),('It permanently cures all hyperandrogenism','Effects vary and the syndrome can persist.')],
 'Metformin is not interchangeable with every PCOS therapy', '**The guideline particularly considers metabolic use in adults with BMI at least 25, with individualized use in other settings.**',['GI tolerance and B12 effects matter.','A lower dose with gradual titration may improve tolerance.'], '**Set the expected endpoint.**',['Assess glucose and cardiometabolic risk.','Do not promise that one medicine will meet all fertility, hair and cycle goals.'],[['Primary rationale','Metabolic improvement'],['Monitoring','Tolerance and B12 context'],['Other goals','May need additional strategies']],[PC])
q('Hirsutism remains troublesome after an adequate contraceptive and cosmetic-treatment trial. What is essential before adding an antiandrogen?', 'Reliable contraception and counseling about fetal risk',[
 ('Antiandrogens are safe in an unrecognized pregnancy without precautions','They can affect fetal development.'),('A single negative test permanently removes pregnancy risk','Ongoing prevention is needed.'),('All agents have identical liver and electrolyte profiles','Drug-specific safety matters.')],
 'Adjunct symptom treatment requires reproductive safety', '**Antiandrogens can be considered after an insufficient response, often after at least six months.**',['Choice depends on effectiveness and toxicity.','Spironolactone requires relevant potassium and renal review.'], '**Use a clear response and monitoring plan.**',['Reassess the severity and original diagnosis if the course is atypical.','Avoid indefinite escalation without benefit.'],[['When','Persistent symptoms after adequate trial'],['Essential','Effective contraception'],['Monitoring','Agent-specific safety']],[PC])
q('A patient with PCOS has prolonged untreated amenorrhea. Which preventive issue needs attention?', 'Endometrial protection from prolonged unopposed estrogen exposure',[
 ('Amenorrhea guarantees a protected endometrium','Chronic anovulation can permit endometrial proliferation.'),('Every patient needs routine biopsy at every visit','Investigation is guided by symptoms and risk.'),('Only androgen concentration determines endometrial risk','Bleeding pattern, weight and metabolic factors also matter.')],
 'Cycle management can prevent a complication beyond irregular bleeding', '**Longstanding untreated amenorrhea increases endometrial hyperplasia risk.**',['Combined hormonal treatment or periodic progestogen can be appropriate.','Abnormal bleeding needs assessment rather than simple reassurance.'], '**Individualize the protection plan.**',['Pregnancy goals and contraindications affect choice.','Do not confuse routine risk reduction with universal invasive screening.'],[['Mechanism','Chronic anovulation'],['Concern','Hyperplasia/endometrial risk'],['Prevention','Appropriate progestogen exposure']],[PC],'clinical_scenario')
q('Anovulatory infertility is attributed to PCOS and no other infertility factor is found. Which is the preferred first-line ovulation-induction drug?', 'Letrozole',[
 ('Metformin as the most effective universal first ovulation agent','It can help selected patients, but more effective ovulation agents exist.'),('Spironolactone','It is an antiandrogen and is unsuitable as a fertility treatment.'),('A combined contraceptive during the conception attempt','It prevents rather than induces ovulation.')],
 'The fertility goal changes the treatment pathway', '**Letrozole is recommended first line in the international guideline for this setting.**',['Confirm that pregnancy is not already present.','Partner and tubal factors should be assessed as clinically appropriate.'], '**Provide preconception risk optimization.**',['Discuss nutrition, folate, metabolic status and treatment monitoring.','Escalate through a specialist pathway if first-line treatment fails.'],[['Indication','Anovulatory PCOS infertility'],['First drug','Letrozole'],['Prerequisite','Exclude current pregnancy and other factors']],[PC],'clinical_scenario')
q('Why should pregnancy planning in PCOS include early glycemic and blood-pressure review?', 'PCOS is associated with increased risks of gestational diabetes and hypertensive pregnancy complications',[
 ('A normal BMI eliminates all increased pregnancy risk','Risk is not confined to high BMI.'),('Conception proves all metabolic abnormalities have resolved','Pregnancy can reveal additional vulnerability.'),('Metformin must automatically be continued to prevent every pregnancy complication','Benefits and indications require individualized evidence-based review.')],
 'Fertility success is followed by a higher-risk antenatal context', '**The guideline recommends preconception assessment and appropriate pregnancy monitoring.**',['Lifestyle, smoking, alcohol, sleep and folate needs should be reviewed.','The exact treatment plan depends on the person and local obstetric guidance.'], '**Coordinate care beyond ovulation induction.**',['Avoid promising that one medication removes all risks.','Explain a practical testing and follow-up plan.'],[['Risks','GDM and hypertensive complications'],['Before conception','Metabolic and health review'],['During pregnancy','Appropriate enhanced monitoring']],[PC])
